using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;
namespace Skywright.Editor {
public static class FinishedMeadowAuthor {
 const string D="Assets/Resources/FinishedMeadow",A="Assets/ALP_Assets/Nature Package - Forest Environment_",P=A+"/_Vegetation/URP/URP_Prefabs/";
 static System.Random rng;static float R(float a,float b)=>Mathf.Lerp(a,b,(float)rng.NextDouble());
 static Dictionary<Material,Material> materials=new();static GameObject[] trees,bushes,plants;static GameObject stone,fern;static Material grass;
 static T Save<T>(T obj,string name)where T:UnityEngine.Object{string path=D+"/"+name;var old=AssetDatabase.LoadAssetAtPath<T>(path);if(old){EditorUtility.CopySerialized(obj,old);UnityEngine.Object.DestroyImmediate(obj);EditorUtility.SetDirty(old);return old;}AssetDatabase.CreateAsset(obj,path);return obj;}
 static Transform Child(Transform p,string name){var g=new GameObject(name);g.transform.SetParent(p,false);return g.transform;}
 static Material Adapt(Material original){if(!original)return null;if(materials.TryGetValue(original,out var m))return m;m=new Material(original);m.enableInstancing=true;if(m.HasProperty("_Brightness"))m.SetFloat("_Brightness",1.06f);foreach(var key in new[]{"_WindLocalIntensity","_LocalWindStrength"})if(m.HasProperty(key))m.SetFloat(key,.14f);if(m.HasProperty("_WindGlobalIntensity"))m.SetFloat("_WindGlobalIntensity",.16f);if(m.HasProperty("_SmoothnessMax"))m.SetFloat("_SmoothnessMax",.14f);if(m.HasProperty("_Cull"))m.SetFloat("_Cull",0);m=Save(m,original.name+"_Meadow.mat");materials[original]=m;return m;}
 static GameObject AdaptPrefab(string name,bool tree){var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(P+name+"_URP.prefab"));g.name=name;g.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);foreach(var c in g.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);foreach(var r in g.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(Adapt).ToArray();r.renderingLayerMask=1;}
  foreach(var group in g.GetComponentsInChildren<LODGroup>()){var lods=group.GetLODs().Where(l=>!tree||l.renderers.Sum(r=>r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3)>16).ToArray();for(int i=0;i<lods.Length;i++){lods[i].screenRelativeTransitionHeight=tree?(i==lods.Length-1?.007f:.32f*Mathf.Pow(.35f,i)):(i==lods.Length-1?.008f:i==0?.16f:.06f);lods[i].fadeTransitionWidth=.25f;}var keep=lods.SelectMany(l=>l.renderers).ToHashSet();foreach(var r in group.GetLODs().SelectMany(l=>l.renderers).Where(r=>!keep.Contains(r)))UnityEngine.Object.DestroyImmediate(r.gameObject);group.fadeMode=LODFadeMode.CrossFade;group.animateCrossFading=true;group.SetLODs(lods);group.RecalculateBounds();}
  var result=PrefabUtility.SaveAsPrefabAsset(g,D+"/"+name+".prefab");UnityEngine.Object.DestroyImmediate(g);return result;}
 static Texture2D Texture(string path,bool normal=false){var importer=AssetImporter.GetAtPath(path) as TextureImporter;if(importer){importer.maxTextureSize=2048;importer.anisoLevel=8;importer.mipmapEnabled=true;importer.textureCompression=TextureImporterCompression.CompressedHQ;importer.textureType=normal?TextureImporterType.NormalMap:TextureImporterType.Default;importer.sRGBTexture=!normal;importer.alphaIsTransparency=path.EndsWith(".tga");importer.SaveAndReimport();}return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 public static void Prepare(){Directory.CreateDirectory(D);materials.Clear();rng=new System.Random(182019);AssetDatabase.Refresh();
  // Source meshes must be readable for explicit offline baking. Runtime scenery does not mutate them.
  foreach(var guid in AssetDatabase.FindAssets("t:Model",new[]{A})){var im=(ModelImporter)AssetImporter.GetAtPath(AssetDatabase.GUIDToAssetPath(guid));im.isReadable=true;im.SaveAndReimport();}
  trees=new[]{AdaptPrefab("MapleSpringTree01",true),AdaptPrefab("MapleSpringTree03",true),AdaptPrefab("ForestTree01",true),AdaptPrefab("ForestTree03",true)};bushes=new[]{AdaptPrefab("ForestBush01",false),AdaptPrefab("ForestBush02",false),AdaptPrefab("MapleSpringBushes01",false)};plants=new[]{AdaptPrefab("GrassPlant03",false),AdaptPrefab("GrassPlant04",false),AdaptPrefab("FlowerGrass01",false),AdaptPrefab("FlowerGrass03",false)};
  stone=Resources.Load<GameObject>("MountainAero/Limestone");fern=Resources.Load<GameObject>("MountainAero/Fern");
  grass=new Material(Shader.Find("Skywright/MeadowGrass"));grass.SetTexture("_BaseMap",Texture(A+"/GrassTextures/Grass01.tga"));grass.SetColor("_BaseColor",new Color(1.12f,1.27f,.94f));grass.enableInstancing=true;grass=Save(grass,"MeadowGrass.mat");
  var ground=Resources.Load<Material>("MountainAero/Ground");ground.SetTexture("_Grass",Texture(A+"/GroundTextures/GroundGrass01.tif"));ground.SetTexture("_GrassNormal",Texture(A+"/GroundTextures/GroundGrass01_N.png",true));ground.SetTexture("_Soil",Texture(A+"/GroundTextures/PathGround01.tif"));ground.SetTexture("_SoilNormal",Texture(A+"/GroundTextures/PathGround01_N.png",true));ground.SetTexture("_Litter",Texture(A+"/GroundTextures/GroundForest01.tif"));ground.SetTexture("_Rock",Texture("Assets/NaturalAero/Textures/Rock030_Color.jpg"));ground.SetTexture("_RockNormal",Texture("Assets/NaturalAero/Textures/Rock030_NormalGL.jpg",true));EditorUtility.SetDirty(ground);HarvestTree();
 }
 public static void HarvestTree(){var source=Resources.Load<GameObject>("FinishedMeadow/MapleSpringTree01");var root=new GameObject("Meadow harvesting maple");var group=root.AddComponent<LODGroup>();var lods=new List<LOD>();Mesh scarSurface=null;
  int index=0;foreach(var lod in source.GetComponent<LODGroup>().GetLODs()){
   var renderers=new List<Renderer>();foreach(var r in lod.renderers){var mf=r.GetComponent<MeshFilter>();var mesh=UnityEngine.Object.Instantiate(mf.sharedMesh);var vertices=mesh.vertices;var bark=new HashSet<int>();var mats=r.sharedMaterials;for(int s=0;s<mesh.subMeshCount;s++)if(mats[Mathf.Min(s,mats.Length-1)].name.StartsWith("bark"))foreach(var id in mesh.GetTriangles(s))bark.Add(id);
    var transform=source.transform.worldToLocalMatrix*mf.transform.localToWorldMatrix;
    for(int i=0;i<vertices.Length;i++){var p=transform.MultiplyPoint3x4(vertices[i])*.36f;vertices[i]=p;}
    mesh.vertices=vertices;var normals=mesh.normals;for(int ni=0;ni<normals.Length;ni++)normals[ni]=transform.MultiplyVector(normals[ni]).normalized;mesh.normals=normals;mesh.RecalculateTangents();mesh.RecalculateBounds();mesh=Save(mesh,"Harvest_LOD"+index+".asset");var child=Child(root.transform,"Maple LOD "+index).gameObject;child.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=child.AddComponent<MeshRenderer>();renderer.sharedMaterials=mats;renderers.Add(renderer);
    if(index==0){var scan=new Mesh{name="Harvest bark surface"};scan.vertices=vertices;var tris=new List<int>();for(int s=0;s<mesh.subMeshCount;s++)if(mats[Mathf.Min(s,mats.Length-1)].name.StartsWith("bark"))tris.AddRange(mesh.GetTriangles(s));scan.triangles=tris.ToArray();scan.RecalculateNormals();scan.RecalculateBounds();scarSurface=Save(scan,"HarvestBarkSurface.asset");}
   }lods.Add(new LOD(index==0?.30f:index==1?.10f:.008f,renderers.ToArray()));index++;
  }
  group.fadeMode=LODFadeMode.CrossFade;group.animateCrossFading=true;group.SetLODs(lods.ToArray());group.RecalculateBounds();var present=root.AddComponent<TreeSurfacePresentation>();present.surface=scarSurface;var scar=new Material(Shader.Find("Universal Render Pipeline/Lit"));scar.color=new Color(.25f,.13f,.055f);scar.SetFloat("_Smoothness",.02f);scar.SetFloat("_Cull",0);present.scarMaterial=Save(scar,"BarkScar.mat");PrefabUtility.SaveAsPrefabAsset(root,D+"/HarvestTree.prefab");UnityEngine.Object.DestroyImmediate(root);
 }
 static GameObject Place(GameObject prefab,Transform root,float x,float z,float scale,float yaw,float embed=0){var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab);g.transform.SetParent(root,false);g.transform.localPosition=new Vector3(x,MountainAeroAuthor.SurfaceHeight(x,z)-embed,z);g.transform.localRotation=Quaternion.Euler(0,yaw,0);g.transform.localScale=Vector3.one*scale;return g;}
 static bool Home(float x,float z)=>x>-10&&x<12&&z>-25&&z< -10;
 static bool NearNode(float x,float z,float radius){return EarthTrial.Locations.Any(p=>Vector2.Distance(new Vector2(x,z),new Vector2(p.x,p.z))<radius);}
 static bool Clear(float x,float z)=>Home(x,z)||MountainAeroAuthor.RouteDistance(x,z)<2.4f||NearNode(x,z,1.0f);
 public static void Dress(Transform root){
  var old=root.Find("Authored woodland");if(old){int i=0;foreach(Transform tr in old){float scale=tr.localScale.x;var g=Place(trees[i++%trees.Length],root,tr.position.x,tr.position.z,scale*.26f,tr.eulerAngles.y,.12f);g.name="Woodland tree";var c=g.AddComponent<CapsuleCollider>();c.center=new Vector3(0,4,0);c.height=8;c.radius=.28f;}UnityEngine.Object.DestroyImmediate(old.gameObject);}
  var oldPlants=root.Find("Ground plants");if(oldPlants)UnityEngine.Object.DestroyImmediate(oldPlants.gameObject);
  var woodland=Child(root,"Finished woodland edge");var rocks=Child(root,"Composed limestone groups");var cover=Child(root,"Finished meadow ground cover");
  var groups=new[]{new Vector2(-27,-13),new Vector2(-31,0),new Vector2(-34,14),new Vector2(-39,29),new Vector2(24,19)};
  int k=0;foreach(var p in groups){var tree=Place(trees[k++%trees.Length],woodland,p.x,p.y,R(.48f,.66f),R(0,360),.15f);var c=tree.AddComponent<CapsuleCollider>();c.center=new Vector3(0,4,0);c.height=8;c.radius=.3f;
   for(int i=0;i<9;i++){float a=R(0,6.28f),r=R(2,6),x=p.x+Mathf.Cos(a)*r,z=p.y+Mathf.Sin(a)*r;if(Clear(x,z))continue;Place(bushes[i%3],woodland,x,z,i%3==2?R(.3f,.48f):R(.5f,.9f),R(0,360),.04f);}
   for(int i=0;i<22;i++){float x=p.x+R(-6,6),z=p.y+R(-6,6);if(Clear(x,z))continue;Place(i%3==0?fern:plants[i%2],cover,x,z,R(.35f,.65f),R(0,360),.025f);}
  }
  foreach(var p in new[]{new Vector2(-21,-24),new Vector2(-25,13),new Vector2(-37,22),new Vector2(23,-25),new Vector2(-48,38)}){
   Rock(rocks,p.x,p.y,R(2.1f,3.0f),R(0,360));
   for(int i=0;i<7;i++){float a=R(0,6.28f),r=R(1.3f,3.8f),x=p.x+Mathf.Cos(a)*r,z=p.y+Mathf.Sin(a)*r;if(Clear(x,z))continue;Rock(rocks,x,z,i<3?R(.6f,1.2f):R(.16f,.35f),R(0,360));Place(fern,cover,x+.4f,z+.35f,R(.35f,.65f),R(0,360),.015f);}
  }
  for(int i=0;i<160;i++){float x=R(-35,25),z=R(-26,28);if(Clear(x,z)||NearNode(x,z,1.8f)||Mathf.PerlinNoise(x*.16f+20,z*.16f+30)<.55f)continue;Place(plants[2+i%2],cover,x,z,R(.25f,.5f),R(0,360),.015f);}
  Grass(cover);Cliff(root);Neighbors(root);RockSilhouettes(root);AssetDatabase.SaveAssets();
 }
 static void Rock(Transform parent,float x,float z,float size,float yaw){var g=Place(stone,parent,x,z,size,yaw,size*.2f);var f=g.transform.Find("LOD 2").GetComponentInChildren<MeshFilter>();f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;}
 static void Grass(Transform root){
  for(int tz=-30;tz<30;tz+=6)for(int tx=-36;tx<24;tx+=6){var v=new List<Vector3>();var ns=new List<Vector3>();var uvs=new List<Vector2>();var colors=new List<Color>();var tr=new List<int>();
   for(int i=0;i<560;i++){float x=R(tx,tx+6),z=R(tz,tz+6);if(Home(x,z))continue;float path=MountainAeroAuthor.RouteDistance(x,z);float noise=Mathf.PerlinNoise(x*.12f+3,z*.12f+9);if(path<1.1f||NearNode(x,z,.52f)||noise<.26f||R(0,1)>Mathf.Lerp(.38f,.96f,noise))continue;float h=R(.18f,.39f)*Mathf.Lerp(.38f,1,Mathf.SmoothStep(0,1,(path-1.1f)/1.8f));float width=R(.32f,.54f),yaw=R(0,360);var center=new Vector3(x,MountainAeroAuthor.SurfaceHeight(x,z)-.025f,z);var color=Color.Lerp(new Color(.78f,.88f,.68f),new Color(1.10f,1.07f,.85f),R(0,1));
    for(int card=0;card<3;card++){int start=v.Count;var q=Quaternion.Euler(0,yaw+card*62,0);for(int row=0;row<4;row++){float t=row/3f;for(int side=0;side<2;side++){v.Add(center+q*new Vector3((side-.5f)*width,t*h,t*t*h*.24f));ns.Add((q*new Vector3(0,.92f,.38f)).normalized);uvs.Add(new Vector2(side,t));colors.Add(color);}}for(int row=0;row<3;row++){int a=start+row*2;tr.AddRange(new[]{a,a+2,a+1,a+1,a+2,a+3});}}
   }
   if(v.Count==0)continue;var mesh=new Mesh{name="Curved meadow clumps",indexFormat=IndexFormat.UInt32};mesh.SetVertices(v);mesh.SetNormals(ns);mesh.SetUVs(0,uvs);mesh.SetColors(colors);mesh.SetTriangles(tr,0);mesh.RecalculateBounds();mesh=Save(mesh,"Clumps_"+tx+"_"+tz+".asset");var obj=Child(root,"Grass clumps "+tx+" "+tz).gameObject;obj.AddComponent<MeshFilter>().sharedMesh=mesh;obj.AddComponent<MeshRenderer>().sharedMaterial=grass;
  }
 }
 static GameObject Landform(string name,Transform root,Material material){var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/FinishedMeadow/Models/"+name+".fbx"),root);g.name=name;foreach(var r in g.GetComponentsInChildren<Renderer>())r.sharedMaterial=material;return g;}
 static void Cliff(Transform root){var mat=Resources.Load<Material>("MountainAero/Ground");var p=Child(root,"Weathered southern cliff ledges");for(int i=0;i<20;i++){float x=-36+i*3.8f;float z=x< -20?-42+(x+20)*.91f:x<32?-42+(x+20)*4/52f:-38-(x-32)*62/68f;var g=Landform("LimestoneButtress_"+i%3,p,mat);float sy=R(1.3f,2.3f);g.transform.localScale=new Vector3(R(1.25f,1.65f),sy,R(1.0f,1.5f));g.transform.localPosition=new Vector3(x,MountainAeroAuthor.SurfaceHeight(x,z)-sy*7-.15f,z+.3f);g.transform.localRotation=Quaternion.Euler(0,R(-30,30),0);foreach(var f in g.GetComponentsInChildren<MeshFilter>()){var c=f.gameObject.AddComponent<MeshCollider>();c.sharedMesh=f.sharedMesh;f.gameObject.AddComponent<EarthSurface>();}}
 }
 static void Neighbors(Transform root){foreach(Transform c in root.Cast<Transform>().ToArray())if(c.name.StartsWith("Distant island")||c.name.StartsWith("ScenicIsland_"))UnityEngine.Object.DestroyImmediate(c.gameObject);var mat=Resources.Load<Material>("MountainAero/Ground");for(int i=0;i<3;i++){var g=Landform("ScenicIsland_"+i,root,mat);g.transform.localPosition=i==0?new Vector3(820,-30,100):i==1?new Vector3(-170,-80,-900):new Vector3(-1000,20,650);}}
 static void RockSilhouettes(Transform root){
  var existing=root.Find("Embedded cliff rock faces");if(existing)UnityEngine.Object.DestroyImmediate(existing.gameObject);var group=Child(root,"Embedded cliff rock faces");var rock=Resources.Load<GameObject>("MountainAero/Limestone");int i=0;
  foreach(float x in new[]{-26f,-19f,-11f,-6f,2f,9f,18f,25f,32f}){var g=(GameObject)PrefabUtility.InstantiatePrefab(rock);g.transform.SetParent(group,false);float z=x< -20?-42+(x+20)*.91f:-42+(x+20)*4/52;g.transform.localPosition=new Vector3(x,-4.0f-(i%3)*1.25f,z);g.transform.localRotation=Quaternion.Euler(30+i%3*18,i*71,12);g.transform.localScale=new Vector3(2.8f+i%3*.55f,2.8f+i%2,3.0f);var f=g.transform.Find("LOD 2").GetComponentInChildren<MeshFilter>();f.gameObject.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;f.gameObject.AddComponent<EarthSurface>();i++;}
  for(int n=0;n<3;n++){var island=root.Find("ScenicIsland_"+n);if(!island)continue;foreach(var f in island.GetComponentsInChildren<MeshFilter>()){var m=UnityEngine.Object.Instantiate(f.sharedMesh);m.colors=Enumerable.Repeat(Color.black,m.vertexCount).ToArray();f.sharedMesh=Save(m,"ScenicIsland_"+n+"_Surface.asset");}
  }
 }
 public static void PolishExistingAndBuild(){Directory.CreateDirectory(D);var path="Assets/Resources/MountainAero/Island.prefab";var g=PrefabUtility.LoadPrefabContents(path);try{Neighbors(g.transform);RockSilhouettes(g.transform);PrefabUtility.SaveAsPrefabAsset(g,path);}finally{PrefabUtility.UnloadPrefabContents(g);}AssetDatabase.SaveAssets();MountainAeroAuthor.Build();}
 public static void AuthorAndBuild(){var identities=SceneryHarvestAuthor.Existing();MountainAeroAuthor.Author();Prepare();var p="Assets/Resources/MountainAero/Island.prefab";var g=PrefabUtility.LoadPrefabContents(p);try{Dress(g.transform);SceneryHarvestAuthor.Assign(g.transform,identities);PrefabUtility.SaveAsPrefabAsset(g,p);}finally{PrefabUtility.UnloadPrefabContents(g);}MountainAeroAuthor.Build();}
}
}
